{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH || join(root, 'workboard.sqlite');
const database = new DatabaseSync(dbPath);
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  )
  ;
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0
  );
`);

const listProjects = database.prepare('SELECT id, name FROM projects ORDER BY id');
const getProject = database.prepare('SELECT id, name FROM projects WHERE id = ?');
const createProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = database.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const createTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const getTask = database.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE id = ? AND project_id = ?');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');

function sendJson(response, status, value) {
  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

async function readRequestBody(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  return JSON.parse(body);
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');

  if (request.method === 'GET' && url.pathname === '/health') {
    sendJson(response, 200, { status: 'ok' });
    return;
  }

  if (request.method === 'GET' && url.pathname === '/api/projects') {
    sendJson(response, 200, listProjects.all());
    return;
  }

  if (request.method === 'POST' && url.pathname === '/api/projects') {
    let body;
    try {
      body = await readRequestBody(request);
    } catch {
      sendJson(response, 400, { error: 'Invalid request body' });
      return;
    }
    const name = typeof body?.name === 'string' ? body.name.trim() : '';
    if (!name) {
      sendJson(response, 400, { error: 'Project name is required' });
      return;
    }
    const result = createProject.run(name);
    sendJson(response, 201, getProject.get(Number(result.lastInsertRowid)));
    return;
  }

  const taskRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
  if (taskRoute) {
    const projectId = Number(taskRoute[1]);
    if (!Number.isSafeInteger(projectId) || !getProject.get(projectId)) {
      sendJson(response, 404, { error: 'Project not found' });
      return;
    }
    if (request.method === 'GET' && !taskRoute[2]) {
      sendJson(response, 200, listTasks.all(projectId));
      return;
    }
    if (request.method === 'POST' && !taskRoute[2]) {
      let body;
      try { body = await readRequestBody(request); } catch {
        sendJson(response, 400, { error: 'Invalid request body' });
        return;
      }
      const title = typeof body?.title === 'string' ? body.title.trim() : '';
      if (!title) {
        sendJson(response, 400, { error: 'Task title is required' });
        return;
      }
      const result = createTask.run(projectId, title);
      sendJson(response, 201, getTask.get(Number(result.lastInsertRowid), projectId));
      return;
    }
    if (request.method === 'PATCH' && taskRoute[2]) {
      let body;
      try { body = await readRequestBody(request); } catch {
        sendJson(response, 400, { error: 'Invalid request body' });
        return;
      }
      const taskId = Number(taskRoute[2]);
      if (typeof body?.completed !== 'boolean') {
        sendJson(response, 400, { error: 'Completion state is required' });
        return;
      }
      if (!getTask.get(taskId, projectId)) {
        sendJson(response, 404, { error: 'Task not found' });
        return;
      }
      updateTask.run(body.completed ? 1 : 0, taskId, projectId);
      sendJson(response, 200, getTask.get(taskId, projectId));
      return;
    }
  }

  if (request.method === 'GET' && url.pathname.startsWith('/projects/')) {
    const id = Number(url.pathname.slice('/projects/'.length));
    if (Number.isSafeInteger(id) && id > 0 && getProject.get(id)) {
      response.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      response.end(await readFile(join(root, 'index.html')));
      return;
    }
  }

  if (request.method === 'GET' && url.pathname === '/') {
    response.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    response.end(await readFile(join(root, 'index.html')));
    return;
  }

  if (request.method === 'GET' && url.pathname === '/app.js') {
    response.writeHead(200, { 'content-type': 'text/javascript; charset=utf-8' });
    response.end(await readFile(join(root, 'app.js')));
    return;
  }

  if (request.method === 'GET' && url.pathname === '/style.css') {
    response.writeHead(200, { 'content-type': 'text/css; charset=utf-8' });
    response.end(await readFile(join(root, 'style.css')));
    return;
  }

  sendJson(response, 404, { error: 'Not found' });
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');
const listView = document.querySelector('#project-list');
const detailView = document.querySelector('#project-detail');
const projectContainer = document.querySelector('#projects');
const form = document.querySelector('#create-project-form');
const nameInput = document.querySelector('#project-name');
const errorMessage = document.querySelector('#project-error');
const taskContainer = document.querySelector('#tasks');
const taskForm = document.querySelector('#create-task-form');
const taskInput = document.querySelector('#task-title');
const taskError = document.querySelector('#task-error');
const taskFilter = document.querySelector('#task-filter');
let activeProject = null;
let tasks = [];

async function request(path, options) {
  const response = await fetch(path, options);
  const value = await response.json();
  if (!response.ok) throw new Error(value.error || 'Request failed');
  return value;
}

function showList() {
  activeProject = null;
  listView.hidden = false;
  detailView.hidden = true;
  document.title = 'Workboard';
}

function showProject(project) {
  activeProject = project;
  listView.hidden = true;
  detailView.hidden = false;
  document.querySelector('#project-title').textContent = project.name;
  document.title = `${project.name} · Workboard`;
  taskFilter.value = 'All';
  refreshTasks();
}

function renderTasks() {
  taskContainer.replaceChildren();
  const visibleTasks = tasks.filter((task) => taskFilter.value === 'All'
    || (taskFilter.value === 'Open' && !task.completed)
    || (taskFilter.value === 'Completed' && task.completed));
  for (const task of visibleTasks) {
    const row = document.createElement('div');
    row.className = 'task-row';
    row.dataset.testid = 'task-row';
    const title = document.createElement('span');
    title.textContent = task.title;
    const label = document.createElement('label');
    label.className = 'task-completion';
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = Boolean(task.completed);
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      try {
        await request(`/api/projects/${activeProject.id}/tasks/${task.id}`, {
          method: 'PATCH', headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked })
        });
        task.completed = checkbox.checked;
        renderTasks();
      } catch (error) {
        checkbox.checked = !checkbox.checked;
        taskError.textContent = error.message;
        taskError.hidden = false;
      }
    });
    label.append(checkbox);
    row.append(title, label);
    taskContainer.append(row);
  }
}

async function refreshTasks() {
  if (!activeProject) return;
  try {
    tasks = await request(`/api/projects/${activeProject.id}/tasks`);
    renderTasks();
  } catch (error) {
    taskError.textContent = error.message;
    taskError.hidden = false;
  }
}

function renderProjects(projects) {
  projectContainer.replaceChildren();
  for (const project of projects) {
    const row = document.createElement('div');
    row.className = 'project-row';
    row.dataset.testid = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const open = document.createElement('button');
    open.type = 'button';
    open.textContent = 'Open project';
    open.addEventListener('click', () => {
      history.pushState({}, '', `/projects/${project.id}`);
      showProject(project);
    });
    row.append(name, open);
    projectContainer.append(row);
  }
}

async function refreshProjects() {
  renderProjects(await request('/api/projects'));
}

async function renderRoute() {
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (!match) {
    showList();
    await refreshProjects();
    return;
  }
  try {
    const projects = await request('/api/projects');
    const project = projects.find((item) => item.id === Number(match[1]));
    if (!project) {
      history.replaceState({}, '', '/');
      showList();
      await refreshProjects();
      return;
    }
    showProject(project);
  } catch {
    showList();
  }
}

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  errorMessage.hidden = true;
  try {
    await request('/api/projects', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ name: nameInput.value.trim() })
    });
    nameInput.value = '';
    await refreshProjects();
  } catch (error) {
    errorMessage.textContent = error.message;
    errorMessage.hidden = false;
  }
});

taskForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  taskError.hidden = true;
  try {
    await request(`/api/projects/${activeProject.id}/tasks`, {
      method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ title: taskInput.value.trim() })
    });
    taskInput.value = '';
    await refreshTasks();
  } catch (error) {
    taskError.textContent = error.message;
    taskError.hidden = false;
  }
});

taskFilter.addEventListener('change', renderTasks);

document.querySelector('#back-to-projects').addEventListener('click', () => {
  history.pushState({}, '', '/');
  showList();
  refreshProjects();
});

window.addEventListener('popstate', renderRoute);
renderRoute();
